var i=`0961-tamago-sando`;var a=`world-0961`;var s=`JP`;var t=`east-asia`;var o=4;var d=33;var g={en:`Tamago Sando`,ua:`Сендвіч із яйцем тамаго`};var r={en:`Tamago Sando is a Japan dish made with chicken egg, mayonnaise, yellow mustard, milk bread. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сендвіч із яйцем тамаго, страва кухні країни Японія. Основні складники: куряче яйце, майонез, жовта гірчиця, молочний хліб. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var l=[{en:`Boil the eggs for about 10 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 10 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:10,i:[[`chicken-egg`,6,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`mayonnaise`,110,`g`],[`yellow-mustard`,15,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]},{en:`Arrange the prepared cooked components and listed toppings in a serving dish, keeping hot foods hot and chilled components cold until serving.`,ua:`Складіть готові приготовлені компоненти й зазначені додатки в посуді для подавання, підтримуючи гаряче гарячим, а холодне охолодженим.`,t:[`layered-assembly`,`garnishing`],m:12,i:[[`milk-bread`,8,`slice`],[`unsalted-butter`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`green-onion`,20,`g`]]}];var m={slug:i,id:a,country:`JP`,region:t,servings:4,minutes:33,title:g,text:r,steps:l};export{s as country,m as default,a as id,d as minutes,t as region,o as servings,i as slug,l as steps,r as text,g as title};